<template>
  <section class="h-full w-full flex flex-col gap-4">
    <PageTitle title="Work Shift" show-doc />
    <Card class="w-full p-6 mx-auto flex flex-col gap-6">
      <LabeledSelect
        v-model="selectValue"
        :items="projectsList"
        label="Project"
        placeholder="Select a project"
        :disabled="starting || isLoadingProjectsList"
        :is-loading="isLoadingProjectsList"
        :error="error ? error?.data?.detail || 'Failed to load projects for work shift' : undefined"
        @update:model-value="onSelectProject"
      />

      <div class="flex flex-row justify-center gap-4">
        <Button
          class="w-full"
          variant="default"
          size="lg"
          :disabled="starting || !selectedProject || isLoadingProjectsList"
          :loading="starting"
          @click="handleStartClick"
        >
          {{ starting ? 'Starting…' : 'Start Shift' }}
        </Button>
      </div>
    </Card>

    <UnsyncedShiftAlert v-if="hasUnsyncedRecords" :count="unsyncedShiftIds.length" :syncing="syncing" @sync="syncNow" />

    <WorkShiftUploadProgress />

    <PermissionToggles :project="selectedProject" />

    <div class="flex flex-col gap-2">
      <h3 class="text-lg font-semibold">Recent Work Shifts</h3>
      <AppLoader v-if="isLoadingRecentShifts" variant="inline" subject="recent work shifts" />
      <AppError v-else-if="recentShiftsError" title="Failed to load recent work shifts" :error="recentShiftsError" />
      <AppEmpty v-else-if="!recentShifts || recentShifts.items.length === 0" subject="recent work shifts" />
      <NuxtLink
        v-for="item in recentShifts?.items"
        v-else
        :key="item.id"
        :to="{ name: 'workshifts-id', params: { id: item.id } }"
      >
        <Card class="p-4 flex flex-col gap-1">
          <div class="flex items-center justify-between gap-2">
            <p class="text-base font-medium line-clamp-1">{{ item.project.name }}</p>
            <Badge :variant="getWorkshiftStatusBadge(item.status).variant" class="shrink-0">
              {{ getWorkshiftStatusBadge(item.status).label }}
            </Badge>
          </div>
          <div class="text-sm text-muted-foreground">
            {{ formatDateTzToFormat(item.start_time, 'MM/dd/yyyy, hh:mm aaa', timezone) }}
            —
            <template v-if="item.end_time">
              {{
                isSameDay(formatDateToTz(item.start_time, timezone), formatDateToTz(item.end_time, timezone))
                  ? formatDateTzToFormat(item.end_time, 'hh:mm aaa', timezone)
                  : formatDateTzToFormat(item.end_time, 'MM/dd/yyyy, hh:mm aaa', timezone)
              }}
            </template>
            <span v-else>Ongoing</span>
          </div>
          <div v-if="item.net_hours != null" class="text-sm text-muted-foreground">
            Net: {{ formatHoursDuration(item.net_hours) }}
          </div>
        </Card>
      </NuxtLink>
    </div>
  </section>
</template>

<script setup lang="ts">
useSeoMeta({
  title: 'Work Shift',
  description: 'Start or end your work shift.',
});

definePageMeta({
  roles: ['canvasser', 'subcontractor_canvasser'],
  platform: 'mobile',
  middleware: ['shift-guard'],
  backLabel: 'work shift',
});

import { checkForUnsyncedData } from '~/utils/useDb';
import { processError } from '~/utils/mobile/processError';
import type { SelectorProjectItem } from '~/client';
import { getWorkShiftList, type GetWorkShiftListResponse } from '~/client';
import { useMobileRuntimeState } from '~/composables/mobile/useMobileRuntimeState';
import { useMobilePermissions } from '~/composables/mobile/useMobilePermissions';
import { useWorkShiftProject } from '~/composables/mobile/projects/useWorkShiftProject';
import { formatDateTzToFormat, formatDateToTz } from '~/utils/formatDateToFormat';
import { isSameDay } from 'date-fns';
import { getWorkshiftStatusBadge } from '~/constants/workshifts/workshiftStatuses';

const { unsyncedShiftIds, hasNetworkError, lastUploadHadErrors } = useMobileRuntimeState();
const { start, syncDataWithProgress } = useMobile()!;
const { projects, isLoading: isLoadingProjectsList, error, projectStatuses, projectType } = useSelectorProjectList();
const { refresh } = useMobilePermissions();
const { load: loadSavedProject } = useWorkShiftProject();
const selectedProject = ref<SelectorProjectItem | null>(null);
const selectValue = ref<SelectItem | null>(null);
const route = useRoute('shift');
const { timezone } = useUserRole();

const {
  data: recentShifts,
  isLoading: isLoadingRecentShifts,
  error: recentShiftsError,
} = useQuery({
  key: () => ['recent-workshifts'],
  query: (): Promise<GetWorkShiftListResponse> =>
    getWorkShiftList({
      composable: '$fetch',
      query: {
        page: 1,
        size: 5,
        sort_by: 'start_time',
        sort_type: 'desc',
        timezone: timezone.value,
      },
    }),
  staleTime: 0,
});

onBeforeMount(() => {
  projectStatuses.value = ['active'];
  projectType.value = null;
});

const projectsList = computed<SelectItem[]>(() => {
  return projects.value
    ? projects.value.map((p) => ({
        name: p.name,
        value: p.id,
      }))
    : [];
});

const onSelectProject = (item: SelectItem | null) => {
  selectedProject.value = item ? (projects.value?.find((p) => p.id === item.value) ?? null) : null;
};

function preselectProject(projectId: string) {
  const match = projects.value?.find((p) => p.id === projectId);
  if (match) {
    selectedProject.value = match;
    selectValue.value = { name: match.name, value: match.id };
  }
}

const syncing = ref(false);
const starting = ref(false);
const hasUnsyncedRecords = computed(() => unsyncedShiftIds.value.length > 0);

const syncNow = async () => {
  if (syncing.value) return;
  if (servingOffline.value) {
    showOfflineToastError();
    return;
  }
  syncing.value = true;
  try {
    await syncDataWithProgress();
    if (servingOffline.value) {
      showOfflineToastError();
    } else if (lastUploadHadErrors.value) {
      showToastError('Some data failed to upload. Please try again.');
    } else {
      showToastSuccess('All data uploaded successfully');
    }
  } catch (e: any) {
    if (!hasNetworkError.value) {
      processError(e);
    }
  } finally {
    syncing.value = false;
  }
};

const handleStartClick = async () => {
  if (!selectedProject.value) return;
  if (servingOffline.value) {
    showOfflineToastError();
    return;
  }
  starting.value = true;
  try {
    const workShiftId = await start(selectedProject.value);
    await refresh();
    if (workShiftId) {
      await navigateTo({ name: 'shift-id', params: { id: workShiftId } }, { replace: true });
    }
  } catch (e: any) {
    processError(e);
  } finally {
    starting.value = false;
  }
};

watch(hasNetworkError, (isError, wasError) => {
  if (wasError && !isError && hasUnsyncedRecords.value) {
    syncNow();
  }
});

const prefillProjectId = computed(() => {
  return (route.query.project_id as string) || null;
});

const pendingProjectId = ref<string | null>(null);

watch(projects, (list) => {
  if (selectedProject.value || !list?.length) return;
  const targetId = prefillProjectId.value || pendingProjectId.value;
  if (targetId) {
    preselectProject(targetId);
  }
});

onMounted(async () => {
  unsyncedShiftIds.value = await checkForUnsyncedData();

  if (prefillProjectId.value && projects.value?.length) {
    preselectProject(prefillProjectId.value);
  } else if (!prefillProjectId.value) {
    const savedProject = await loadSavedProject();
    if (savedProject) {
      pendingProjectId.value = savedProject.id;
      if (projects.value?.length) {
        preselectProject(savedProject.id);
      }
    }
  }
});
</script>
